export type HandleGizmoTheme = {
    /**
     * - The color where the shapes are visible.
     */
    base: Color;
    /**
     * - The color where the scene hides the shapes.
     */
    occluded: Color;
    /**
     * - The color of filled volumes. An alpha of 0 skips the volumes.
     */
    fill: Color;
    /**
     * - The color of a hovered or dragged radius, range, width or far clip
     * handle, and of its guide and readout label.
     */
    primary: Color;
    /**
     * - The color of a hovered or dragged height, near clip or inner cone
     * angle handle, and of its guide and readout label.
     */
    secondary: Color;
    /**
     * - The color of a hovered or dragged depth, field of view or outer cone
     * angle handle, and of its guide and readout label.
     */
    tertiary: Color;
    /**
     * - The color of a hovered or dragged box corner handle.
     */
    corner: Color;
    /**
     * - The color of the disc behind each icon, which is clicked to select it.
     */
    backdrop: Color;
};
/**
 * A handle placed this frame, or the one being dragged.
 */
export type GizmoHandle = {
    /**
     * - The handle shape.
     */
    shape: Shape | null;
    /**
     * - The node the handle edits, or null for a shape gizmo.
     */
    node: GraphNode | null;
    /**
     * - The value the handle edits.
     */
    name: string;
    /**
     * - The index of the handle among those editing the value.
     */
    index: number;
    /**
     * - The point the edit is measured from.
     */
    origin: Vec3;
    /**
     * - The unit direction of the line, or the normal of the plane.
     */
    dir: Vec3;
    /**
     * - Whether the handle moves in a plane rather than along a line.
     */
    plane: boolean;
};
/**
 * The handles of a box and how they resize it.
 */
export type BoxHandleOptions = {
    /**
     * - Whether to show handles at the center of each face.
     */
    faceHandles: boolean;
    /**
     * - Whether to show handles at the corners.
     */
    cornerHandles: boolean;
    /**
     * - Whether a resize keeps the center in place.
     */
    centered: boolean;
    /**
     * - Whether a corner handle scales the box evenly.
     */
    uniform: boolean;
};
